<?php
require __DIR__.'/auxiliary_contract.php';
require APPPATH.'services/NativeCompanyCatalogCurrencySchema.php';
$db->query("CREATE TABLE {$p}currencies(id INTEGER PRIMARY KEY,name TEXT,symbol TEXT,isdefault INT)");
$db->query("INSERT INTO {$p}currencies VALUES(1,'BRL','R$',1),(2,'USD','$',0)");
$db->query("CREATE TABLE {$p}items(id INTEGER PRIMARY KEY,description TEXT,rate DECIMAL(15,2))");
$db->query("INSERT INTO {$p}items(id,description,rate) VALUES(1,'Historical untouched','12.30')");
$before=$db->query("SELECT * FROM {$p}items")->row_array();
essentialCheck(NativeCompanyCatalogCurrencySchema::installedPrecision($db,$p)===2,'precision comes from persisted native rate metadata');
NativeCompanyCatalogCurrencySchema::ensure($db,$p,NativeCompanyCatalogCurrencySchema::installedPrecision($db,$p));
NativeCompanyCatalogCurrencySchema::ensure($db,$p,2);
$ids=NativeCompanyCatalogCurrencySchema::currencyIds($db,$p);NativeCompanyCatalogCurrencySchema::assertReady($db,$p,$ids);
$after=$db->query("SELECT * FROM {$p}items")->row_array();
essentialCheck(array_intersect_key($after,$before)===$before,'currency preparation preserves every historical value');
foreach($ids as$id)essentialCheck(array_key_exists('rate_currency_'.$id,$after)&&$after['rate_currency_'.$id]===null,'only installed currency columns added empty');
$db->trans_begin();settingThrows(fn()=>NativeCompanyCatalogCurrencySchema::ensure($db,$p,2),'issuer_outer_transaction_not_allowed','DDL cannot commit caller transaction');essentialCheck($db->pdo->inTransaction(),'caller remains owned by caller');$db->trans_rollback();
settingThrows(fn()=>NativeCompanyCatalogCurrencySchema::assertReady($db,$p,[999999]),'native_catalog_currency_schema_invalid','unknown currency not accepted');
settingThrows(fn()=>NativeCompanyCatalogCurrencySchema::ensure($db,$p,16),'native_catalog_currency_precision_invalid','precision bounded to native decimal precision');
$db->query("INSERT INTO {$p}currencies(id,name,symbol,isdefault) VALUES(999,'XYZ','x',0)");
$db->query("ALTER TABLE {$p}items ADD COLUMN rate_currency_999 TEXT");
settingThrows(fn()=>NativeCompanyCatalogCurrencySchema::ensure($db,$p,2),'native_catalog_currency_schema_invalid','unexpected existing type not silently rewritten');
echo "Native currency schema replay, historical preservation, metadata and transaction guards: passed.\n";
